CREATE TABLE `payment_disposition_drafts` (`id` varchar(64) NOT NULL,`tenant_id` bigint NOT NULL,`incident_id` varchar(64) NOT NULL,`created_by` bigint NOT NULL,`approved_by` bigint NULL,`action_type` varchar(64) NOT NULL,`status` varchar(32) NOT NULL,`idempotency_key` varchar(128) NOT NULL,`execution_result` text NOT NULL,`created_at` datetime(3) NOT NULL,`updated_at` datetime(3) NOT NULL,PRIMARY KEY (`id`),UNIQUE KEY `uq_payment_drafts_tenant_key` (`tenant_id`,`idempotency_key`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
